// A failed search is not evidence of zero commercial opportunities.
const sourceResponses=$input.all();
const sourceQueries=$('Requêtes').all();
if(sourceResponses.length!==sourceQueries.length)throw new Error('W7_SEARCH_SOURCE_FAILED: response count mismatch; inspect source execution; no automatic replay');
for(let index=0;index<sourceResponses.length;index++){
  const response=sourceResponses[index]?.json;
  const body=response?.body&&typeof response.body==='object'?response.body:response;
  const status=Number(response?.statusCode??200);
  if(!response||response.error||!Number.isFinite(status)||status<200||status>=300||!body||body.error||!Array.isArray(body.data))
    throw new Error('W7_SEARCH_SOURCE_FAILED: query '+(index+1)+'; inspect source execution; no automatic replay');
}
const FREE = new Set(['gmail.com','yahoo.fr','yahoo.com','hotmail.fr','hotmail.com','outlook.fr','outlook.com','live.fr','orange.fr','wanadoo.fr','free.fr','sfr.fr','laposte.net','icloud.com','gmx.fr','neuf.fr','bbox.fr']);
const dom = e => String(e || '').toLowerCase().split('@')[1] || '';

const BAD = /pagesjaunes|houzz|facebook|instagram|linkedin|societe\.com|pappers|infogreffe|verif\.com|yelp|tripadvisor|google\.|youtube|wikipedia|leboncoin|seloger|bienici|logic-immo|meilleursagents|travaux\.com|habitatpresto|starofservice|mappy|118712|annuaire|kompass|manageo|indeed|welcometothejungle|batiweb|companeo|quotatis|ootravaux|hellowork|doctrine|trustpilot|lefigaro|leparisien|ouest-france|20minutes|apple\.com|cylex|hoodspot|justacote|foncia\.com|century21|laforet|orpi|guy-hoquet|stephaneplazaimmobilier|nexity|wixsite|business\.site|pagesperso|mairie|gouv\.fr|ville-|paris\.fr/i;
const known = new Set($('Leads').all().map(i => dom(i.json.email)).concat($('Leads').all().map(i => String(i.json.site || '').toLowerCase().replace(/^www\./, ''))).concat($('Blacklist').all().map(i => dom(i.json.email))).filter(x => x && !FREE.has(x)));
const seen = new Set(), out = [];
$input.all().forEach((it, i) => {
  const q = $('Requêtes').all()[i]?.json;
  if (!q || it.json.error) return;
  const body = it.json.body && typeof it.json.body === 'object' ? it.json.body : it.json;
  for (const r of (body.data || [])) {
    const mm = String(r.url || '').match(/^(https?):\/\/([^\/?#:]+)/i); if (!mm) continue;
    const host = mm[2].toLowerCase().replace(/^www\./, '');
    if (BAD.test(host) || seen.has(host) || (!q.test && known.has(host))) continue;
    seen.add(host);
    out.push({ json: { url: `https://${mm[2].toLowerCase()}/`, host, nom: String(r.title || host).replace(/\s*[|–-].*$/, '').slice(0, 120), sigle: '', title: r.title || '', desc: r.description || '', type: q.type, ville: q.ville, departement: q.departement, test: !!q.test, origine: 'oxylabs' } });
  }
});
return out.slice(0, 25);

const iso=()=>new Date().toISOString();
const paris=()=>new Date().toLocaleString('sv-SE',{timeZone:'Europe/Paris'}).slice(0,19);
const day=()=>paris().slice(0,10);
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const mail=v=>String(v||'').toLowerCase().trim();
const hash=s=>{let a=2166136261,b=5381;for(const c of String(s)){a=Math.imul(a^c.charCodeAt(0),16777619);b=Math.imul(b,33)^c.charCodeAt(0);}return (a>>>0).toString(16).padStart(8,'0')+(b>>>0).toString(16).padStart(8,'0');};
const FREE=new Set(['gmail.com','yahoo.fr','yahoo.com','hotmail.fr','hotmail.com','outlook.fr','outlook.com','live.fr','orange.fr','wanadoo.fr','free.fr','sfr.fr','laposte.net','icloud.com','gmx.fr','neuf.fr','bbox.fr']);
