const f=$('Final').first().json;const src=$('Emails').all().map(i=>i.json);const existing=$('Radar – Queue').all().map(i=>i.json);const out=[];for(const l of f.rows||[]){const key='prospect:'+company(l);if(existing.some(t=>t.task_key===key))continue;const p=src.find(x=>mail(x.email)===mail(l.email))||{};const prompt=String(p.prompt||'');const evidence=prompt.includes('Extrait du site : ')?prompt.split('Extrait du site : ')[1].split('\n\nRéponds')[0]:'';const need=/(recherch(?:e|ons)|besoin|appel.{0,4}offres|consultation).{0,100}(sous.?trait|artisan|entreprise|travaux|r[eé]nov)|(sous.?trait|artisan).{0,80}(recherch|partenair)/i.exec(evidence);const score=Math.min(100,55+(FREE.has(mail(l.email).split('@')[1])?0:15)+(l.departement?10:0)+(need?25:0));const grade=need&&score>=85?'HOT':score>=65?'WARM':'COLD';out.push(jq(row(key,'prospect',grade,'W3',grade==='HOT'?'approved':'needs_review',{email:l.email,company:company(l),entreprise:l.entreprise,type:l.type,opportunity_type:l.type,location:[l.ville,l.departement?'('+l.departement+')':''].filter(Boolean).join(' '),ville:l.ville||'',departement:l.departement||'',source:l.source,source_url:p.url||('https://'+l.site+'/'),discovered_at:iso(),score,grade,evidence:need?need[0]:'Profil pertinent sans demande de travaux explicite',site:l.site},grade==='HOT'?'Outreach qualifié pendant les heures ouvrées':'Qualification humaine avant tout premier contact','W7')));}const slot=[6,10,14,18].filter(h=>Number(paris().slice(11,13))>=h).pop();out.push(jq(row('radar:'+day()+':'+slot,'radar_run','WARM','W7','done',{new_leads:f.rows?.length||0,queries:$('Requêtes').all().length},'Prochaine rotation','W7')));return out;
